A. SELECT S.name&nbsp;
   FROM Students S&nbsp;
   WHERE EXISTS (SELECT * FROM Enrolled E&nbsp; 
                 WHERE E.courseno = 1470 
                          AND E.rollno = S.rollno);

B. SELECT S.name&nbsp;
   FROM Students S&nbsp;
   WHERE SIZEOF (SELECT * FROM Enrolled E 
                 WHERE E.courseno = 1470 
                         AND E.rollno = S.rollno) > 0;

C. SELECT S.name&nbsp;
   FROM Students S 
   WHERE&nbsp;0 < (SELECT COUNT(*)&nbsp;
              FROM Enrolled E&nbsp;&nbsp;
              WHERE E.courseno = 1470 
                        AND E.rollno&nbsp;=&nbsp;S.rollno);

D. SELECT S.name&nbsp;
   FROM Students S NATURAL JOIN Enrolled E 
   WHERE E.courseno = 1470;
